"""Frozen causal terminal-tail policy artifact (zlib-compressed JSON)."""

import base64
import json
import zlib
from functools import lru_cache

# Generated from the provenance-verified ten-attempt development population.
_DATA = """"""


@lru_cache(maxsize=1)
def load_policy_data():
    return json.loads(zlib.decompress(base64.b64decode(_DATA)).decode("utf-8"))
